def transform(grid):
    """Recolor any complete monochrome row or column to marker color 2."""
    h, w = len(grid), len(grid[0])
    marked_rows = {r for r in range(h) if len(set(grid[r])) == 1}
    marked_cols = {c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1}
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if r in marked_rows or c in marked_cols:
                out[r][c] = 2
    return out
